CREATE TABLE videos (id text PRIMARY KEY, project_id text NOT NULL REFERENCES projects(id), title text NOT NULL, original_name text NOT NULL, extension text NOT NULL, size bigint NOT NULL CHECK(size>0), origin text NOT NULL DEFAULT '', context text NOT NULL DEFAULT '', sensitivity text NOT NULL CHECK(sensitivity IN ('public','internal','sensitive')), status text NOT NULL DEFAULT 'uploading', sha256 text, metadata jsonb, error text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE upload_chunks (video_id text NOT NULL REFERENCES videos(id), number integer NOT NULL CHECK(number>=0), size integer NOT NULL, sha256 text NOT NULL, PRIMARY KEY(video_id,number));
CREATE TABLE runs (id text PRIMARY KEY, video_id text NOT NULL REFERENCES videos(id), status text NOT NULL DEFAULT 'queued', config jsonb NOT NULL, version integer NOT NULL, error text, approved_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(video_id,version));
CREATE TABLE stages (run_id text NOT NULL REFERENCES runs(id), name text NOT NULL, status text NOT NULL DEFAULT 'pending', result jsonb, error text, updated_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(run_id,name));
CREATE TABLE revisions (id bigserial PRIMARY KEY, run_id text NOT NULL REFERENCES runs(id), kind text NOT NULL, item_id text NOT NULL, before_value jsonb NOT NULL, after_value jsonb NOT NULL, actor_id text NOT NULL REFERENCES users(id), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE claims (id text PRIMARY KEY, run_id text NOT NULL REFERENCES runs(id), type text NOT NULL, title text NOT NULL, description text NOT NULL, classification text NOT NULL CHECK(classification IN ('observed','narrated','inferred','unknown')), confidence real NOT NULL CHECK(confidence>=0 AND confidence<=1), review_status text NOT NULL DEFAULT 'pending' CHECK(review_status IN ('pending','approved','rejected','confirm')), evidence jsonb NOT NULL, origin text NOT NULL, prompt_version text NOT NULL, model_profile text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX videos_by_project ON videos(project_id,created_at);
CREATE INDEX runs_by_video ON runs(video_id,created_at);
